import http from 'node:http';
let filas;
function reset(){filas={pedidos_manuales:[{id:'00000000-0000-4000-8000-000000000001',estado:'pagado',estado_entrega:'pendiente_preparar',metodo:'sinpe',total_productos:500,costo_envio:0,total_cobrar:500,comprobante_path:null,correo_cliente_en:'2026-10-13',correo_pago_en:'2026-10-13',creado_en:'2026-10-13T12:00:00Z',cliente:{nombre:'Retiro',apellidos:'QA',modalidad:'retiro'},articulos:[{nombre:'Producto QA',cantidad:1}]}],pedidos_tilopay:[{id:'00000000-0000-4000-8000-000000000002',estado:'pagado',estado_entrega:'pendiente_preparar',entorno:'produccion',total:500,creado_en:'2026-10-13T12:00:00Z',cliente:{nombre:'Envío',apellidos:'QA',modalidad:'envio'},articulos:[]},{id:'00000000-0000-4000-8000-000000000003',estado:'rechazado',resultado_tilopay:'Fondos insuficientes',estado_entrega:'pendiente_preparar',entorno:'produccion',total:500,creado_en:'2026-10-13T12:00:00Z',cliente:{nombre:'Rechazado',apellidos:'QA'},articulos:[]}]};}reset();
http.createServer(async(req,res)=>{res.setHeader('Content-Type','application/json');const url=new URL(req.url,'http://127.0.0.1:3135');if(url.pathname==='/health')return res.end('{}');if(url.pathname==='/reset'){reset();if(url.searchParams.has('archivos')){filas.pedidos_manuales[0].estado_entrega='entregado';}return res.end('{}');}
 const tabla=url.pathname.split('/').at(-1),rows=filas[tabla];if(!rows)return res.end('[]');
 const matches=rows.filter(row=>{const a=url.searchParams.get('archivado_en');if(a==='is.null'&&row.archivado_en)return false;if(a==='not.is.null'&&!row.archivado_en)return false;if(a?.startsWith('eq.')&&a!=='eq.'+row.archivado_en)return false;return ['id','estado','estado_entrega'].every(k=>!url.searchParams.get(k)||url.searchParams.get(k)==='eq.'+row[k]);});
 if(req.method==='PATCH'){let raw='';for await(const chunk of req)raw+=chunk;const cambios=JSON.parse(raw);for(const row of matches)Object.assign(row,cambios);}
 const single=req.headers.accept?.includes('vnd.pgrst.object');return res.end(JSON.stringify(single?matches[0]??null:matches));
}).listen(3135,'127.0.0.1');
